{
  "technical_and_design_decisions": [
    "For U1: Java chaincode TransactionalContext will be implemented as a per-transaction scoped object using thread-local storage to ensure thread safety, injected as the first parameter to chaincode methods to match Node.js behavior, with performance testing to validate minimal overhead for single-threaded transaction processing.",
    "For U2/U3: The protos/utils to protoutils migration will preserve all existing utility and extension functionality, with backward compatibility aliases added to the original protos/utils package for one full release cycle to avoid breaking existing consumer code.",
    "For U4: The Kafka health check backport to 1.4 LTS will reuse the existing health check logic from the master branch with only minimal modifications required to align with 1.4's existing API and configuration surfaces, no changes to core Kafka orderer consensus logic will be made.",
    "For U5: The new ReadOnlyInvoke method will enforce strict validation to reject any state-modifying operations (Put, Delete, etc.) and will be accessible to users with the channel Reader permission, reusing existing chaincode invocation validation logic where possible.",
    "For U6: The new `peer.discovery.externalEndpoint` configuration option will take precedence over the existing PEER_GOSSIP_EXTERNALENDPOINT environment variable for Service Discovery endpoint advertisements, with no changes required to the underlying Service Discovery protocol.",
    "For U7: The operations service `/version` endpoint will return a static version string matching the current Fabric component build version, with no dynamic version resolution logic required.",
    "For U8: Golang sample refactoring will preserve all existing functional behavior of samples, only updating code style, structure, and adding beginner-focused inline comments to explain Fabric-specific patterns."
  ],
  "assumptions": [
    "The backport of Kafka health checks to 1.4 LTS does not require modifications to the underlying Kafka orderer consensus implementation, only porting of existing health check logic from the master branch.",
    "The protos cleanup (U2/U3) does not require changes to any generated proto files, only relocation of existing utility and extension code, so no proto schema changes are needed.",
    "All implemented changes will be validated against the existing Fabric 1.4 LTS test suite, and no new test infrastructure is required for any of the user stories.",
    "The read-only invoke (U5) will reuse existing chaincode invocation validation and access control logic, only adding new checks for operation type and Reader role permissions.",
    "The service discovery external endpoint (U6) will not require changes to the existing Service Discovery protocol, only modification of the endpoint value advertised to client SDKs.",
    "The operations service version endpoint (U7) will return a static version string matching the current Fabric component build version, no dynamic version resolution or external version lookup is required.",
    "The Golang sample refactoring (U8) will not modify the functional behavior of any samples, only code style, structure, and documentation."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "U1 Transactional Context Implementation",
      "activity_description": "Design and implement per-transaction scoped TransactionalContext for Java chaincode, including thread-safe instance creation via thread-local storage, injection as the first chaincode method parameter to match Node.js behavior, stub/API access implementation, and unit/performance testing to validate thread safety and minimal overhead.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A2",
      "activity_name": "U2/U3 Protos Utils Migration",
      "activity_description": "Move all utility functions, extensions, and non-generated code from the protos/utils package to a new top-level protoutils package, update all internal import references across the Fabric codebase, add backward compatibility aliases in the original protos/utils package for one release cycle, and run unit tests to validate no regressions.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A3",
      "activity_name": "U4 Kafka Health Check Backport to 1.4 LTS",
      "activity_description": "Backport existing Kafka orderer health check logic from the master branch to the Fabric 1.4 LTS release branch, make minimal modifications to align with 1.4's existing API and configuration surfaces, and add unit/integration tests for the health check functionality in the 1.4 codebase.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A4",
      "activity_name": "U5 Read-Only Invoke Implementation",
      "activity_description": "Implement new ReadOnlyInvoke chaincode invocation method, add access control logic to allow channel Reader role to call ReadOnlyInvoke, add validation to reject all state-modifying operations (Put, Delete, etc.) in ReadOnlyInvoke calls, and add unit/integration tests for access control and operation validation.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A5",
      "activity_name": "U6 Service Discovery External Endpoint Configuration",
      "activity_description": "Add new `peer.discovery.externalEndpoint` peer configuration option that takes precedence over the PEER_GOSSIP_EXTERNALENDPOINT environment variable for Service Discovery endpoint advertisements, update Service Discovery logic to use the new config value, and add unit tests for configuration precedence and advertisement behavior.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "U7 Operations Service Version Endpoint",
      "activity_description": "Add `/version` endpoint to peer and orderer operations services that returns the current Fabric component build version, update operations service documentation to include the new endpoint, and add unit tests for the endpoint functionality.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "U8 Golang Sample Refactoring",
      "activity_description": "Refactor all existing Fabric Golang samples to follow idiomatic Go conventions (error handling, context usage, naming, package structure), add inline comments explaining Fabric-specific patterns for beginner developers, and validate all refactored samples execute correctly with no functional changes.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A8",
      "activity_name": "Integration Testing and Regression Validation",
      "activity_description": "Run full Fabric integration test suite against all implemented changes to validate no regressions in existing functionality, resolve any issues identified during testing, and perform cross-feature validation to ensure all user stories work as expected together.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 200
  }
}

